import React,{useEffect,useState} from 'react';import{createRoot}from'react-dom/client';import{createClient}from'@supabase/supabase-js';import{EmailAuthForm}from'../../src/components/store/member-email-auth-form';import{MemberEmailProfile}from'../../src/components/store/member-email-profile';import{createEmailAuthClient}from'../../src/lib/member-email-auth.mjs';import{createUsernameClient}from'../../src/lib/member-username-client.mjs';import{MEMBER_TERMS_VERSION,MEMBER_PRIVACY_VERSION}from'../../src/lib/member-consent.mjs';
const client=createClient(location.origin,(window as any).testAnonKey,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}}),api=createEmailAuthClient({auth:client.auth,trustedOrigin:location.origin,confirmationRedirectTo:location.origin+'/return',recoveryRedirectTo:location.origin+'/return',signupAllowed:true}),username=createUsernameClient({url:location.origin,key:(window as any).testAnonKey,auth:client.auth});const consent={terms:{href:'/terms/',version:MEMBER_TERMS_VERSION},privacy:{href:'/privacy/',version:MEMBER_PRIVACY_VERSION},register:(email:string,password:string,evidence:any,draft:any)=>api.signUp(email,password,evidence,draft)};
function App(){const[user,setUser]=useState<string|null>(null);useEffect(()=>{const {data}=client.auth.onAuthStateChange((_event,session)=>setUser(session?.user.id||null));return()=>data.subscription.unsubscribe()},[]);return <><EmailAuthForm auth={api} initialMode="signup" allowSignup signupConsent={consent} signedIn={Boolean(user)} usernameSignIn={username.signIn} checkUsername={username.checkUsername}/>{user&&<MemberEmailProfile key={user} client={client} userId={user} checkUsername={username.checkUsername}/>}</>};createRoot(document.getElementById('root')!).render(<App/>);
